import React, { useState, useEffect } from 'react';
import axios from 'axios';

interface VoiceInterviewProps {
  onBack: () => void;
}

const VoiceInterview: React.FC<VoiceInterviewProps> = ({ onBack }) => {
  const [session, setSession] = useState<any>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string>('');
  const [transcript, setTranscript] = useState<string>('');
  const [interviewerState, setInterviewerState] = useState<string>('idle');
  const [profile, setProfile] = useState<any>(null);
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const [interviewType, setInterviewType] = useState('Technical Interview');
  const [targetRole, setTargetRole] = useState('AI Engineer');
  const [difficulty, setDifficulty] = useState('Mid-Level');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleResumeUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setResumeFile(file);
      setLoading(true);
      setError(null);
      const formData = new FormData();
      formData.append('file', file);

      try {
        const response = await axios.post('http://localhost:8000/api/interview/upload-resume', formData);
        setProfile(response.data.profile);
      } catch (error: any) {
        console.error('Error uploading resume:', error);
        setError('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
      } finally {
        setLoading(false);
      }
    }
  };

  const startVoiceInterview = async () => {
    if (!profile) {
      setError('Please upload a resume first');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      console.log('Starting voice interview with profile:', profile);
      const response = await axios.post('http://localhost:8000/api/interview/voice/start', {
        profile,
        interview_type: interviewType,
        target_role: targetRole,
        difficulty: difficulty,
        total_questions: 5,
        enable_tts: false,  // Disabled to avoid torch loading delay
        enable_stt: false   // Disabled to avoid torch loading delay
      });
      console.log('Voice interview started:', response.data);
      setSession(response.data.session);
      setInterviewerState('listening');

      // Don't auto-play audio initially - let user click to hear
      // if (response.data.session.current_question) {
      //   playQuestionAudio(response.data.session.current_question);
      // }
    } catch (error: any) {
      console.error('Error starting interview:', error);
      setError('Failed to start interview: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  const playQuestionAudio = async (text: string) => {
    setLoading(true);
    setError(null);

    try {
      console.log('Requesting TTS for:', text);
      const response = await axios.post('http://localhost:8000/api/interview/tts', text, {
        responseType: 'blob',
        headers: {
          'Content-Type': 'text/plain'
        }
      });

      console.log('TTS response received, size:', response.data.size);
      const blob = new Blob([response.data], { type: 'audio/wav' });
      const url = URL.createObjectURL(blob);
      setAudioUrl(url);

      const audio = new Audio(url);
      audio.onended = () => setInterviewerState('listening');
      audio.onerror = (e) => {
        console.error('Audio playback error:', e);
        setError('Failed to play audio. Browser may not support this format.');
      };

      await audio.play();
      console.log('Audio playing successfully');
    } catch (error: any) {
      console.error('Error playing audio:', error);
      setError('TTS failed: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  const submitAnswer = async (audioFile?: File, textAnswer?: string) => {
    setInterviewerState('processing');

    try {
      let finalTextAnswer = textAnswer;

      if (audioFile) {
        // Upload audio and get transcription
        const formData = new FormData();
        formData.append('file', audioFile);
        const sttResponse = await axios.post('http://localhost:8000/api/interview/stt', formData);
        setTranscript(sttResponse.data.text);
        finalTextAnswer = sttResponse.data.text;
      }

      const response = await axios.post('http://localhost:8000/api/interview/voice/answer', {
        session: session,
        audio_file: audioFile ? 'temp_audio.wav' : undefined,
        text_answer: finalTextAnswer
      });

      setSession(response.data.session);

      if (response.data.session.is_completed) {
        setInterviewerState('completed');
      } else {
        setInterviewerState('speaking');
        // Play next question
        if (response.data.session.current_question) {
          playQuestionAudio(response.data.session.current_question);
        }
      }
    } catch (error) {
      console.error('Error submitting answer:', error);
      setInterviewerState('idle');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 to-blue-900 p-8">
      <div className="max-w-4xl mx-auto">
        <button 
          onClick={onBack} 
          className="mb-4 text-white hover:text-gray-300 flex items-center gap-2"
        >
          ← Back
        </button>

        <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-8">
          <h1 className="text-3xl font-bold text-white mb-6">🎙️ Voice Interview</h1>

          {/* Error Display */}
          {error && (
            <div className="bg-red-500/20 border border-red-500 p-4 rounded-lg mb-6">
              <p className="text-red-300">{error}</p>
              <button onClick={() => setError(null)} className="text-red-400 text-sm mt-2 underline">Dismiss</button>
            </div>
          )}

          {/* Resume Upload Section */}
          {!profile && (
            <div className="space-y-4">
              <div>
                <label className="block text-white mb-2">📄 Upload Resume (PDF/DOCX)</label>
                <input
                  type="file"
                  accept=".pdf,.docx,.txt"
                  onChange={handleResumeUpload}
                  className="w-full text-white file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-500 file:text-white hover:file:bg-blue-600"
                />
              </div>

              {profile && (
                <div className="bg-green-500/20 border border-green-500 p-4 rounded-lg">
                  <p className="text-green-300">✅ Resume analyzed successfully!</p>
                  <p className="text-white text-sm mt-2">
                    <strong>Name:</strong> {profile.candidate_name}<br/>
                    <strong>Skills:</strong> {profile.skills?.join(', ')}
                  </p>
                </div>
              )}
            </div>
          )}

          {/* Interview Configuration */}
          {profile && !session && (
            <div className="space-y-4 mt-6">
              <div>
                <label className="block text-white mb-2">Interview Type</label>
                <select
                  value={interviewType}
                  onChange={(e) => setInterviewType(e.target.value)}
                  className="w-full p-3 rounded-lg bg-white/10 text-white border border-white/20"
                >
                  <option value="Technical Interview">Technical Interview</option>
                  <option value="Project Defense">Project Defense</option>
                  <option value="Behavioral Interview">Behavioral Interview</option>
                </select>
              </div>

              <div>
                <label className="block text-white mb-2">Target Role</label>
                <input
                  type="text"
                  value={targetRole}
                  onChange={(e) => setTargetRole(e.target.value)}
                  className="w-full p-3 rounded-lg bg-white/10 text-white border border-white/20"
                />
              </div>

              <div>
                <label className="block text-white mb-2">Difficulty</label>
                <select
                  value={difficulty}
                  onChange={(e) => setDifficulty(e.target.value)}
                  className="w-full p-3 rounded-lg bg-white/10 text-white border border-white/20"
                >
                  <option value="Entry-Level">Entry-Level</option>
                  <option value="Mid-Level">Mid-Level</option>
                  <option value="Senior">Senior</option>
                </select>
              </div>

              <button
                onClick={startVoiceInterview}
                disabled={loading}
                className="w-full bg-blue-500 hover:bg-blue-600 text-white py-3 rounded-lg font-semibold mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? '⏳ Starting...' : '🚀 Start Voice Interview'}
              </button>
            </div>
          )}

          {/* Interviewer State */}
          {session && (
            <div className="text-center mb-8">
              <div className="text-6xl mb-4">
                {interviewerState === 'idle' && '🤖'}
                {interviewerState === 'thinking' && '🧠'}
                {interviewerState === 'speaking' && '🔊'}
                {interviewerState === 'listening' && '🎤'}
                {interviewerState === 'processing' && '⏳'}
              </div>
              <p className="text-white text-lg capitalize">
                {interviewerState === 'idle' && 'Ready'}
                {interviewerState === 'thinking' && 'Analyzing your answer...'}
                {interviewerState === 'speaking' && 'Interviewer is speaking...'}
                {interviewerState === 'listening' && 'Your turn...'}
                {interviewerState === 'processing' && 'Evaluating your response...'}
              </p>
            </div>
          )}

          {/* Current Question */}
          {session && !session.is_completed && (
            <div className="bg-blue-500/20 border-l-4 border-blue-500 p-6 rounded-lg mb-6">
              <p className="text-blue-300 text-sm mb-2 font-semibold">INTERVIEWER QUESTION</p>
              <p className="text-white text-lg">"{session.current_question}"</p>
              <div className="mt-4 flex gap-2">
                <button
                  onClick={() => playQuestionAudio(session.current_question)}
                  disabled={loading}
                  className="bg-purple-500 hover:bg-purple-600 text-white px-4 py-2 rounded-lg disabled:opacity-50"
                >
                  🔊 Play Audio
                </button>
                {audioUrl && (
                  <audio controls src={audioUrl} className="flex-1" />
                )}
              </div>
            </div>
          )}

          {/* Progress */}
          {session && !session.is_completed && (
            <div className="mb-6">
              <div className="flex justify-between text-white mb-2">
                <span>Question {session.current_question_index + 1}/{session.total_questions}</span>
                <span className="text-orange-400">Difficulty: {session.difficulty}</span>
              </div>
              <div className="w-full bg-white/10 rounded-full h-2">
                <div 
                  className="bg-gradient-to-r from-blue-500 to-green-500 h-2 rounded-full transition-all"
                  style={{ width: `${((session.current_question_index + 1) / session.total_questions) * 100}%` }}
                />
              </div>
            </div>
          )}

          {/* Voice Input */}
          {session && !session.is_completed && (
            <div className="space-y-4 mt-6">
              <div className="bg-green-500/20 border-l-4 border-green-500 p-6 rounded-lg">
                <p className="text-green-300 text-sm mb-2 font-semibold">🎤 YOUR RESPONSE</p>

                <div className="space-y-4">
                  <div>
                    <label className="block text-white mb-2 font-semibold">Option 1: Upload Audio Recording</label>
                    <p className="text-gray-400 text-sm mb-2">Record your answer separately and upload the audio file</p>
                    <input
                      type="file"
                      accept="audio/*"
                      onChange={(e) => {
                        const file = e.target.files?.[0];
                        if (file) {
                          setLoading(true);
                          submitAnswer(file);
                        }
                      }}
                      className="w-full text-white file:mr-4 file:py-3 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-green-500 file:text-white hover:file:bg-green-600"
                    />
                  </div>

                  <div className="text-center text-gray-400 py-2">— OR —</div>

                  <div>
                    <label className="block text-white mb-2 font-semibold">Option 2: Type Your Answer</label>
                    <textarea
                      value={transcript}
                      onChange={(e) => setTranscript(e.target.value)}
                      placeholder="Type your answer here..."
                      className="w-full p-4 rounded-lg bg-white/10 text-white border border-white/20 focus:border-green-500 focus:outline-none"
                      rows={4}
                    />
                    <button
                      onClick={() => {
                        if (transcript.trim()) {
                          setLoading(true);
                          submitAnswer(undefined, transcript);
                        }
                      }}
                      disabled={!transcript.trim() || loading}
                      className="w-full bg-green-500 hover:bg-green-600 text-white py-3 rounded-lg font-semibold mt-3 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {loading ? '⏳ Submitting...' : 'Submit Answer'}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Interview Completed */}
          {session && session.is_completed && (
            <div className="text-center">
              <h2 className="text-2xl font-bold text-white mb-4">🎉 Interview Completed!</h2>
              <div className="bg-black/30 p-6 rounded-lg text-left">
                <pre className="text-green-400 overflow-auto max-h-96 text-sm">
                  {JSON.stringify(session.report, null, 2)}
                </pre>
              </div>
              <button
                onClick={() => {
                  setSession(null);
                  setProfile(null);
                  setResumeFile(null);
                }}
                className="mt-4 bg-green-500 hover:bg-green-600 text-white px-6 py-3 rounded-lg font-semibold"
              >
                New Interview
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default VoiceInterview;
